"""Render the bounded independent validation report after all numerical checks pass."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent

def main():
 d=json.loads((HERE/'verification.json').read_text());assert d['status']=='passed' and d['formal_models']==399
 p=d['primary'];s=d['key_secondary'];u=d['unit_identity_diagnostics'][1:]
 fmt=lambda r:f"均值{r['mean']:+.6f}，样本SD={r['sample_sd']:.6f}，最小/最大[{r['min']:+.6f}, {r['max']:+.6f}]，无重抽anchor={r['anchor']:+.6f}"
 lines=['# v2.8 训练样本重抽独立核验报告','','## Material Passport','','- artifact_type: independent_numerical_artifact_validation','- mode: validate','- Verification Status: ANALYZED（数值与产物独立核验通过；未独立重训）','- independence: 同一会话另一助手，不是外部盲审','- scope: 当前经验行样本重抽及保存产物，不认证未知设备独立性或历史来源','','## 核验覆盖','',f"全部21unit完成独立核验：无重抽anchor19模型和20次分层重抽380模型，共{d['formal_models']}正式模型。另有单列2000行接口模型，不计入399。逐unit验证原始CSV、完整有序训练ID、60000位multiplicity、RNG状态、训练/验证/预留边界、重新拟合的中位数与q、全部训练掩码和C/B期望预算。固定验证4输入与测试13输入均由独立代码重建。",'',f"所有399模型均核对完整参数、340维M3输入指纹、原ID绑定、实际100次迭代与未启用内部早停。重载核对{d['probability_arrays']}组单模型概率，最大误差{d['max_prediction_error']:.3g}；{d['candidate_ensemble_arrays']}组候选集成概率及AP、{d['selection_arms']}项C/B选择独立重算通过，AP最大误差{d['max_ap_error']:.3g}，C/B期望逐列预算最大差{d['max_expected_budget_error']:.3g}。候选选择同时用独立AP和保存的精确浮点AP审查，最终选中配置一致。",'',f"每unit选择文件持久保存后才开始测试预测，全部19个测试预测事件绑定选择文件SHA256并与保存文件吻合。完整日志检查通过。{d['summary_statistics']}项全局统计与全部CSV重算通过，最大汇总误差{d['max_summary_error']:.3g}。anchor排除在20次重抽统计之外；样本SD分母为19。冻结文件及各unit核验后的所有产物指纹再次核对。",'',f"20次重抽各包含42000个出现位置，不同原始行ID数范围{min(x['unique_rows'] for x in u)}–{max(x['unique_rows'] for x in u)}；其中不同正类原始行ID数范围{min(x['unique_by_class'][1] for x in u)}–{max(x['unique_by_class'][1] for x in u)}。副本保留原ID，不作为新设备或独立现场观测。",'','## 核对后的描述性结果','',f"主要selected C−selected B在测试S1 30%：{fmt(p)}。",'',f"关键次要固定C025−B025在测试S1 30%：{fmt(s)}。",'',f"20次重抽选择次数：{json.dumps(d['selection_counts'],ensure_ascii=False)}。anchor选择为{json.dumps(d['anchor_choices'],ensure_ascii=False)}。alpha0表示使用当前unit BASE。因此本轮20次selected C−selected B实际比较BASE与所选非零B，不是非零C造成伤害的估计；选择程序和固定非零强度结果分别解释。",'', '以上最小/最大只是20次经验重抽的描述性范围，不是置信区间、预测区间或可靠尾部概率估计。均值减anchor不是自动的偏差估计或校正。','', '## 统计与解释边界检查','', '按ARS实验统计解释清单检查11/11项；不据此给出总体推断或投稿可接受性判定。','', '| 项目 | 检查结果与边界 |','|---|---|','| Simpson反转 | 五压力条件分别报告，不合并成总体效应；保留20个逐unit差值及其min/max。 |','| 生态谬误 | 不将重抽模型平均AP推断为个体风险或外部车队收益。 |','| Berkson选择偏差 | 本轮固定使用APS经验训练池，不能验证或消除原始采集选择机制。 |','| 碰撞变量偏差 | 固定类别数量与训练池仅定义经验条件重抽，不构成现场因果识别。 |','| 基率忽略 | 重抽固定负41300/正700；测试负15625/正375，AP解释限定于此构成，不覆盖基率变化。 |','| 均值回归 | 未按新性能选极端种子；mean-minus-anchor仅描述差异，不解释为偏差校正。 |','| 幸存者偏差 | 预定399模型均完成且有独立核验；无删unit、替换seed或隐去失败。 |','| 多处寻找效应 | 30项流程×对照×压力差值完整报告，另45项候选AP摘要；没有p值或挑显著项。 |','| 分析路径自由度 | 新运行前本地冻结，历史测试结果已可见；仍为回顾性探索，非公开预注册。 |','| 相关即因果 | 新固定100迭代流程与旧auto流程不同；不将新旧差异全部归因重抽或解释为纯机制效应。 |','| 反向因果 | 数据未提供足够设备/时间结构，真实缺失与故障的因果方向不由本实验识别。 |','','## 尚未解决的证据问题','','原CSV特征名匿名化，未提供明确车辆、批次或时间ID。原行ID不交叉及完全相同特征行检查只能给出记录层面的隔离，不能证明设备独立或排除近重复。20次分层重抽不覆盖外层验证/测试样本变化、基率变化、模型/遮蔽/压力种子变化、时间漂移或外部现场总体。','', '关闭内部早停避免同一bootstrap原ID副本进入内部训练/早停验证，但产生了新的固定100迭代流程。anchor重训用于同流程对照，不能沿用旧auto模型冒充该anchor。全候选选择已重新执行；固定C025结果仍不能代表选择程序。','', '独立代码重载模型与复算概率/AP验证产物内在一致性，不是再次从头拟合399个模型，不认证历史来源，也不替代作者贡献、资助、利益冲突或署名声明。', '', '证据文件：verification_preflight.json、verification_units/*.json、verification.json、verification_logs/及验证器源码。每unit receipt保存当时核验器/冻结配置/全部unit产物SHA256；最终检查确认这些来源未改变。']
 (HERE/'validation_report.md').write_text('\n'.join(lines)+'\n')
 print(HERE/'validation_report.md')
if __name__=='__main__':main()
